$files = Get-ChildItem -Filter "frame_*.png" | Sort-Object Name $counter = 0 foreach ($file in $files) { $counter++ $block = [Math]::Ceiling($counter / 20) $posInBlock = (($counter - 1) % 20) + 1 if ($posInBlock -le 10) { $newName = "MENV_B${block}_R${posInBlock}.png" } else { $activNum = $posInBlock - 10 $newName = "MENV_B${block}_A${activNum}.png" } Rename-Item -Path $file.FullName -NewName $newName } Write-Host "Listo: $counter archivos renombrados"